import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import java.time.temporal.TemporalAccessor

import scala.collection.mutable
import scala.util.Try

// ============================================================================
// Structural Types (Protocol equivalents)
// ============================================================================

trait Tokenizable {
  def toToken: String
}

trait HasLength {
  def length: Int
}

trait TokenProcessor[-T] {
  def process(item: T): Unit
}

// ============================================================================
// Enums and Constants
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object StringType extends TokenType { val value = "string" }
  case object Numeric extends TokenType { val value = "numeric" }
  case object Temporal extends TokenType { val value = "temporal" }
  case object Structured extends TokenType { val value = "structured" }
  case object Binary extends TokenType { val value = "binary" }
  case object Null extends TokenType { val value = "null" }
}

// ============================================================================
// Core Token Classes
// ============================================================================

case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {
  def withMetadata(entries: (String, Any)*): Token =
    copy(metadata = metadata ++ entries.toMap)
}

class MutableTokenBatch {
  private val _tokens: mutable.ListBuffer[Token] = mutable.ListBuffer.empty
  private var _processed: Boolean = false

  def add(token: Token): Unit = {
    if (_processed) throw new RuntimeException("Batch already processed")
    _tokens += token
  }

  def tokens: List[Token] = _tokens.toList

  def markProcessed(): Unit = {
    _processed = true
  }
}

// ============================================================================
// Generic Container Classes
// ============================================================================

class TokenContainer[+T](items: Seq[T]) {
  private val _items: Seq[T] = items

  def getAll: Seq[T] = _items

  def mapTokens(func: T => String): List[String] =
    _items.map(func).toList
}

class TokenSink[-T] {
  private val _received: mutable.ListBuffer[Any] = mutable.ListBuffer.empty

  def receive(item: T): Unit = {
    _received += item
  }

  def drain(): List[Any] = {
    val result = _received.toList
    _received.clear()
    result
  }
}

class BivariantHandler[T](default: T) {
  private var _value: T = default

  def get: T = _value

  def set(value: T): Unit = {
    _value = value
  }

  def transform(func: T => T): T = {
    _value = func(_value)
    _value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

abstract class BaseTokenizer[T] {
  def tokenize(value: T): Token

  def tokenizeBatch(values: Iterable[T]): Iterator[Token] =
    values.iterator.map(tokenize)
}

sealed trait StringOrBytes
case class StringValue(value: String) extends StringOrBytes
case class BytesValue(value: Array[Byte]) extends StringOrBytes

class StringTokenizer(
  encoding: String = "UTF-8",
  normalizer: String => String = identity
) extends BaseTokenizer[StringOrBytes] {

  def tokenize(value: StringOrBytes): Token = {
    val strValue = value match {
      case BytesValue(bytes) => new String(bytes, encoding)
      case StringValue(s)    => s
    }
    val normalized = normalizer(strValue)
    Token(normalized, TokenType.StringType)
  }
}

sealed trait NumericValue
case class IntValue(value: Int) extends NumericValue
case class LongValue(value: Long) extends NumericValue
case class FloatValue(value: Float) extends NumericValue
case class DoubleValue(value: Double) extends NumericValue
case class DecimalValue(value: BigDecimal) extends NumericValue

class NumericTokenizer(
  precision: Int = 6,
  formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[NumericValue] {

  def tokenize(value: NumericValue): Token = {
    val (strValue, originalType) = value match {
      case DecimalValue(d) => (s"%%.${precision}f".format(d), "BigDecimal")
      case DoubleValue(d)  => (s"%%.${precision}f".format(d), "Double")
      case FloatValue(f)   => (s"%%.${precision}f".format(f.toDouble), "Float")
      case IntValue(i)     => (i.toString, "Int")
      case LongValue(l)    => (l.toString, "Long")
    }
    Token(strValue, TokenType.Numeric, Map("original_type" -> originalType))
  }
}

sealed trait TemporalValue
case class DateTimeValue(value: LocalDateTime) extends TemporalValue
case class DateValue(value: LocalDate) extends TemporalValue

class TemporalTokenizer(formatStr: Option[String] = None)
  extends BaseTokenizer[TemporalValue] {

  import TemporalTokenizer._

  def tokenize(value: TemporalValue): Token = {
    val fmt = formatStr match {
      case Some(f) => DateTimeFormatter.ofPattern(f)
      case None => value match {
        case _: DateTimeValue => DateTimeFormatter.ofPattern(IsoFormat)
        case _: DateValue     => DateTimeFormatter.ofPattern(DateFormat)
      }
    }

    val formatted = value match {
      case DateTimeValue(dt) => dt.format(fmt)
      case DateValue(d)      => d.format(fmt)
    }

    Token(formatted, TokenType.Temporal)
  }
}

object TemporalTokenizer {
  val IsoFormat: String = "yyyy-MM-dd'T'HH:mm:ss"
  val DateFormat: String = "yyyy-MM-dd"
}

// ============================================================================
// Advanced: Union Types and Overloads
// ============================================================================

class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenize(value: String): Token =
    stringTokenizer.tokenize(StringValue(value))

  def tokenize(value: Array[Byte]): Token =
    stringTokenizer.tokenize(BytesValue(value))

  def tokenize(value: Int): Token =
    numericTokenizer.tokenize(IntValue(value))

  def tokenize(value: Long): Token =
    numericTokenizer.tokenize(LongValue(value))

  def tokenize(value: Float): Token =
    numericTokenizer.tokenize(FloatValue(value))

  def tokenize(value: Double): Token =
    numericTokenizer.tokenize(DoubleValue(value))

  def tokenize(value: BigDecimal): Token =
    numericTokenizer.tokenize(DecimalValue(value))

  def tokenize(value: LocalDateTime): Token =
    temporalTokenizer.tokenize(DateTimeValue(value))

  def tokenize(value: LocalDate): Token =
    temporalTokenizer.tokenize(DateValue(value))

  def tokenize(value: Tokenizable): Token =
    Token(value.toToken, TokenType.Structured)

  def tokenizeAny(value: Any): Token = value match {
    case null               => Token("NULL", TokenType.Null)
    case t: Tokenizable     => Token(t.toToken, TokenType.Structured)
    case s: String          => tokenize(s)
    case b: Array[Byte]     => tokenize(b)
    case i: Int             => tokenize(i)
    case l: Long            => tokenize(l)
    case f: Float           => tokenize(f)
    case d: Double          => tokenize(d)
    case bd: BigDecimal     => tokenize(bd)
    case dt: LocalDateTime  => tokenize(dt)
    case d: LocalDate       => tokenize(d)
    case other              => Token(other.toString, TokenType.StringType, Map("fallback" -> true))
  }
}

// ============================================================================
// Complex Nested Generics
// ============================================================================

class TokenRegistry[T] {
  private val _registry: mutable.Map[String, TokenContainer[T]] = mutable.Map.empty
  private val _handlers: mutable.ListBuffer[T => Option[Token]] = mutable.ListBuffer.empty

  def register(key: String, container: TokenContainer[T]): Unit = {
    _registry(key) = container
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    _handlers += handler
  }

  def process(key: String): List[Option[Token]] = {
    _registry.get(key) match {
      case None => Nil
      case Some(container) =>
        container.getAll.map { item =>
          _handlers.iterator
            .map(handler => handler(item))
            .collectFirst { case Some(token) => token }
        }.toList
    }
  }
}

// ============================================================================
// Higher-Kinded Type Simulation → Proper Functor/Monad
// ============================================================================

class TokenFunctor[T](protected val _value: T) {
  def map[B](func: T => B): TokenFunctor[B] =
    new TokenFunctor(func(_value))

  def flatMap[B](func: T => TokenFunctor[B]): TokenFunctor[B] =
    func(_value)

  def getOrElse[B >: T](default: => B): B =
    if (_value != null) _value else default
}

class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def ap[B](funcWrapped: TokenMonad[T => B]): TokenMonad[B] =
    new TokenMonad(funcWrapped._value(_value))
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

sealed trait JsonValue
case class JsonString(value: String) extends JsonValue
case class JsonInt(value: Int) extends JsonValue
case class JsonDouble(value: Double) extends JsonValue
case class JsonBool(value: Boolean) extends JsonValue
case object JsonNull extends JsonValue
case class JsonArray(items: List[JsonValue]) extends JsonValue
case class JsonObject(fields: Map[String, JsonValue]) extends JsonValue

class JsonTokenizer(pretty: Boolean = false) {
  def tokenize(value: JsonValue): Token = {
    val jsonStr = if (pretty) toJsonString(value, indent = 0)
                  else toJsonStringCompact(value)
    Token(jsonStr, TokenType.Structured, Map("json" -> true))
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.")

    val result = parts.foldLeft(Option(value)) {
      case (None, _) => None
      case (Some(JsonObject(fields)), part) => fields.get(part)
      case (Some(JsonArray(items)), part) =>
        Try(part.toInt).toOption.filter(i => i >= 0 && i < items.length).map(items(_))
      case _ => None
    }

    result.map(tokenize)
  }

  private def toJsonStringCompact(value: JsonValue): String = value match {
    case JsonString(s)      => s""""${escapeJson(s)}""""
    case JsonInt(i)         => i.toString
    case JsonDouble(d)      =>
      if (d == d.toLong && !d.isInfinite) d.toLong.toString
      else d.toString
    case JsonBool(b)        => b.toString
    case JsonNull           => "null"
    case JsonArray(items)   => items.map(toJsonStringCompact).mkString("[", ", ", "]")
    case JsonObject(fields) =>
      fields.map { case (k, v) =>
        s""""${escapeJson(k)}": ${toJsonStringCompact(v)}"""
      }.mkString("{", ", ", "}")
  }

  private def toJsonString(value: JsonValue, indent: Int): String = {
    val pad = "  " * indent
    val padInner = "  " * (indent + 1)
    value match {
      case JsonArray(items) if items.nonEmpty =>
        val entries = items.map(v => padInner + toJsonString(v, indent + 1))
        entries.mkString("[\n", ",\n", s"\n$pad]")
      case JsonObject(fields) if fields.nonEmpty =>
        val entries = fields.map { case (k, v) =>
          s"""$padInner"${escapeJson(k)}": ${toJsonString(v, indent + 1)}"""
        }
        entries.mkString("{\n", ",\n", s"\n$pad}")
      case other => toJsonStringCompact(other)
    }
  }

  private def escapeJson(s: String): String =
    s.replace("\\", "\\\\")
     .replace("\"", "\\\"")
     .replace("\n", "\\n")
     .replace("\r", "\\r")
     .replace("\t", "\\t")
}

